        en: { name: 'Karahayıt red springs', description: 'A hot spring in the village of Karahayıt where iron-rich water stains the terraces not white but rust-red and orange. Locals come here for the thermal baths.', tip: 'The village is 5 kilometres north of Pamukkale; take a minibus or taxi and look for the Kırmızı Su sign in the centre.' },
        es: { name: 'Fuentes rojas de Karahayıt', description: 'Un manantial caliente en el pueblo de Karahayıt donde el agua rica en hierro tiñe las terrazas no de blanco, sino de rojo óxido y naranja. Los lugareños vienen por los baños termales.', tip: 'El pueblo está a 5 kilómetros al norte de Pamukkale: llega en minibús o taxi y busca el cartel de Kırmızı Su en el centro.' },
        de: { name: 'Rote Quellen von Karahayıt', description: 'Eine heiße Quelle im Dorf Karahayıt, deren eisenhaltiges Wasser die Terrassen nicht weiß, sondern rostrot und orange färbt. Einheimische kommen wegen der Thermalbäder.', tip: 'Das Dorf liegt 5 Kilometer nördlich von Pamukkale – fahr mit dem Minibus oder Taxi und folge im Zentrum dem Schild Kırmızı Su.' },
        fr: { name: 'Sources rouges de Karahayıt', description: 'Une source chaude du village de Karahayıt dont l’eau ferrugineuse colore les terrasses non pas en blanc, mais en rouge rouille et en orange. Les habitants y viennent pour les bains thermaux.', tip: 'Le village est à 5 kilomètres au nord de Pamukkale : venez en minibus ou en taxi et suivez le panneau Kırmızı Su dans le centre.' },
        it: { name: 'Sorgenti rosse di Karahayıt', description: 'Una sorgente calda nel villaggio di Karahayıt, dove l’acqua ricca di ferro colora le terrazze non di bianco ma di rosso ruggine e arancione. La gente del posto viene qui per i bagni termali.', tip: 'Il villaggio è a 5 chilometri a nord di Pamukkale: arriva in minibus o in taxi e cerca il cartello Kırmızı Su in centro.' },
